Lib3MF4EOSResult lib3mf4eos_eoscontext_getsupportedsdkversions(Lib3MF4EOS_EOSContext pEOSContext, const Lib3MF4EOS_uint32 nSupportedVersionsBufferSize, Lib3MF4EOS_uint32* pSupportedVersionsNeededChars, char * pSupportedVersionsBuffer)
{
	IBase* pIBaseClass = (IBase *)pEOSContext;

	try {
		if ( (!pSupportedVersionsBuffer) && !(pSupportedVersionsNeededChars) )
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		std::string sSupportedVersions("");
		IEOSContext* pIEOSContext = dynamic_cast<IEOSContext*>(pIBaseClass);
		if (!pIEOSContext)
			throw ELib3MF4EOSInterfaceException(LIB3MF4EOS_ERROR_INVALIDCAST);
		
		bool isCacheCall = (pSupportedVersionsBuffer == nullptr);
		if (isCacheCall) {
			sSupportedVersions = pIEOSContext->GetSupportedSDKVersions();

			pIEOSContext->_setCache (new ParameterCache_1<std::string> (sSupportedVersions));
		}
		else {
			auto cache = dynamic_cast<ParameterCache_1<std::string>*> (pIEOSContext->_getCache ());
			if (cache == nullptr)
				throw ELib3MF4EOSInterfaceException(LIB3MF4EOS_ERROR_INVALIDCAST);
			cache->retrieveData (sSupportedVersions);
			pIEOSContext->_setCache (nullptr);
		}
		
		if (pSupportedVersionsNeededChars)
			*pSupportedVersionsNeededChars = (Lib3MF4EOS_uint32) (sSupportedVersions.size()+1);
		if (pSupportedVersionsBuffer) {
			if (sSupportedVersions.size() >= nSupportedVersionsBufferSize)
				throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_BUFFERTOOSMALL);
			for (size_t iSupportedVersions = 0; iSupportedVersions < sSupportedVersions.size(); iSupportedVersions++)
				pSupportedVersionsBuffer[iSupportedVersions] = sSupportedVersions[iSupportedVersions];
			pSupportedVersionsBuffer[sSupportedVersions.size()] = 0;
		}
		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}

