Lib3MF4EOSResult lib3mf4eos_eoscontext_getmaterialsetrelationshiptype(Lib3MF4EOS_EOSContext pEOSContext, const Lib3MF4EOS_uint32 nRelationshipTypeBufferSize, Lib3MF4EOS_uint32* pRelationshipTypeNeededChars, char * pRelationshipTypeBuffer)
{
	IBase* pIBaseClass = (IBase *)pEOSContext;

	try {
		if ( (!pRelationshipTypeBuffer) && !(pRelationshipTypeNeededChars) )
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		std::string sRelationshipType("");
		IEOSContext* pIEOSContext = dynamic_cast<IEOSContext*>(pIBaseClass);
		if (!pIEOSContext)
			throw ELib3MF4EOSInterfaceException(LIB3MF4EOS_ERROR_INVALIDCAST);
		
		bool isCacheCall = (pRelationshipTypeBuffer == nullptr);
		if (isCacheCall) {
			sRelationshipType = pIEOSContext->GetMaterialSetRelationshipType();

			pIEOSContext->_setCache (new ParameterCache_1<std::string> (sRelationshipType));
		}
		else {
			auto cache = dynamic_cast<ParameterCache_1<std::string>*> (pIEOSContext->_getCache ());
			if (cache == nullptr)
				throw ELib3MF4EOSInterfaceException(LIB3MF4EOS_ERROR_INVALIDCAST);
			cache->retrieveData (sRelationshipType);
			pIEOSContext->_setCache (nullptr);
		}
		
		if (pRelationshipTypeNeededChars)
			*pRelationshipTypeNeededChars = (Lib3MF4EOS_uint32) (sRelationshipType.size()+1);
		if (pRelationshipTypeBuffer) {
			if (sRelationshipType.size() >= nRelationshipTypeBufferSize)
				throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_BUFFERTOOSMALL);
			for (size_t iRelationshipType = 0; iRelationshipType < sRelationshipType.size(); iRelationshipType++)
				pRelationshipTypeBuffer[iRelationshipType] = sRelationshipType[iRelationshipType];
			pRelationshipTypeBuffer[sRelationshipType.size()] = 0;
		}
		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}

