Lib3MF4EOSResult lib3mf4eos_eoscontext_createtaskfrom3mftoolpath(Lib3MF4EOS_EOSContext pEOSContext, Lib3MF_Model pModel, Lib3MF4EOS_MachineConfigFuture pMachineConfiguration, Lib3MF4EOS_EOSToolpathConversionSettings pSettings, const char * pName, const char * pComment, const char * pGeneratorName, const char * pGeneratorVersion, Lib3MF4EOS_TaskCreationFuture * pResult)
{
	IBase* pIBaseClass = (IBase *)pEOSContext;

	try {
		if (pName == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (pComment == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (pGeneratorName == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (pGeneratorVersion == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (pResult == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		Lib3MF::PModel pIModel = std::make_shared<Lib3MF::CModel>(CWrapper::sPLib3MFWrapper.get(), pModel);
		CWrapper::sPLib3MFWrapper->Acquire(pIModel.get());
		if (!pIModel)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDCAST);
		
		IBase* pIBaseClassMachineConfiguration = (IBase *)pMachineConfiguration;
		IMachineConfigFuture* pIMachineConfiguration = dynamic_cast<IMachineConfigFuture*>(pIBaseClassMachineConfiguration);
		if (!pIMachineConfiguration)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDCAST);
		
		IBase* pIBaseClassSettings = (IBase *)pSettings;
		IEOSToolpathConversionSettings* pISettings = dynamic_cast<IEOSToolpathConversionSettings*>(pIBaseClassSettings);
		if (!pISettings)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDCAST);
		
		std::string sName(pName);
		std::string sComment(pComment);
		std::string sGeneratorName(pGeneratorName);
		std::string sGeneratorVersion(pGeneratorVersion);
		IBase* pBaseResult(nullptr);
		IEOSContext* pIEOSContext = dynamic_cast<IEOSContext*>(pIBaseClass);
		if (!pIEOSContext)
			throw ELib3MF4EOSInterfaceException(LIB3MF4EOS_ERROR_INVALIDCAST);
		
		pBaseResult = pIEOSContext->CreateTaskFrom3MFToolpath(pIModel, pIMachineConfiguration, pISettings, sName, sComment, sGeneratorName, sGeneratorVersion);

		*pResult = (IBase*)(pBaseResult);
		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}



