/*************************************************************************************************************************
 Global functions implementation
**************************************************************************************************************************/
Lib3MF4EOSResult lib3mf4eos_getversion(Lib3MF4EOS_uint32 * pMajor, Lib3MF4EOS_uint32 * pMinor, Lib3MF4EOS_uint32 * pMicro)
{
	IBase* pIBaseClass = nullptr;

	try {
		if (!pMajor)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (!pMinor)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (!pMicro)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		CWrapper::GetVersion(*pMajor, *pMinor, *pMicro);

		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}

Lib3MF4EOSResult lib3mf4eos_getlasterror(Lib3MF4EOS_Base pInstance, const Lib3MF4EOS_uint32 nErrorMessageBufferSize, Lib3MF4EOS_uint32* pErrorMessageNeededChars, char * pErrorMessageBuffer, bool * pHasError)
{
	IBase* pIBaseClass = nullptr;

	try {
		if ( (!pErrorMessageBuffer) && !(pErrorMessageNeededChars) )
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (pHasError == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		IBase* pIBaseClassInstance = (IBase *)pInstance;
		IBase* pIInstance = dynamic_cast<IBase*>(pIBaseClassInstance);
		if (!pIInstance)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDCAST);
		
		std::string sErrorMessage("");
		*pHasError = CWrapper::GetLastError(pIInstance, sErrorMessage);

		if (pErrorMessageNeededChars)
			*pErrorMessageNeededChars = (Lib3MF4EOS_uint32) (sErrorMessage.size()+1);
		if (pErrorMessageBuffer) {
			if (sErrorMessage.size() >= nErrorMessageBufferSize)
				throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_BUFFERTOOSMALL);
			for (size_t iErrorMessage = 0; iErrorMessage < sErrorMessage.size(); iErrorMessage++)
				pErrorMessageBuffer[iErrorMessage] = sErrorMessage[iErrorMessage];
			pErrorMessageBuffer[sErrorMessage.size()] = 0;
		}
		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}

Lib3MF4EOSResult lib3mf4eos_releaseinstance(Lib3MF4EOS_Base pInstance)
{
	IBase* pIBaseClass = nullptr;

	try {
		IBase* pIBaseClassInstance = (IBase *)pInstance;
		IBase* pIInstance = dynamic_cast<IBase*>(pIBaseClassInstance);
		if (!pIInstance)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDCAST);
		
		CWrapper::ReleaseInstance(pIInstance);

		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}

Lib3MF4EOSResult lib3mf4eos_acquireinstance(Lib3MF4EOS_Base pInstance)
{
	IBase* pIBaseClass = nullptr;

	try {
		IBase* pIBaseClassInstance = (IBase *)pInstance;
		IBase* pIInstance = dynamic_cast<IBase*>(pIBaseClassInstance);
		if (!pIInstance)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDCAST);
		
		CWrapper::AcquireInstance(pIInstance);

		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}

Lib3MF4EOSResult lib3mf4eos_injectcomponent(const char * pNameSpace, Lib3MF4EOS_pvoid pSymbolAddressMethod)
{
	IBase* pIBaseClass = nullptr;

	try {
		if (pNameSpace == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		std::string sNameSpace(pNameSpace);
		
		bool bNameSpaceFound = false;
		
		if (sNameSpace == "Lib3MF") {
			if (CWrapper::sPLib3MFWrapper.get() != nullptr) {
				throw ELib3MF4EOSInterfaceException(LIB3MF4EOS_ERROR_COULDNOTLOADLIBRARY);
			}
			CWrapper::sPLib3MFWrapper = Lib3MF::CWrapper::loadLibraryFromSymbolLookupMethod(pSymbolAddressMethod);
			bNameSpaceFound = true;
		}
		
		if (!bNameSpaceFound)
			throw ELib3MF4EOSInterfaceException(LIB3MF4EOS_ERROR_COULDNOTLOADLIBRARY);
		
		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}

Lib3MF4EOSResult lib3mf4eos_createcontext(const char * pSDKDirectory, const char * pLogFileName, Lib3MF4EOS_EOSContext * pInstance)
{
	IBase* pIBaseClass = nullptr;

	try {
		if (pSDKDirectory == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (pLogFileName == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		if (pInstance == nullptr)
			throw ELib3MF4EOSInterfaceException (LIB3MF4EOS_ERROR_INVALIDPARAM);
		std::string sSDKDirectory(pSDKDirectory);
		std::string sLogFileName(pLogFileName);
		IBase* pBaseInstance(nullptr);
		pBaseInstance = CWrapper::CreateContext(sSDKDirectory, sLogFileName);

		*pInstance = (IBase*)(pBaseInstance);
		return LIB3MF4EOS_SUCCESS;
	}
	catch (ELib3MF4EOSInterfaceException & Exception) {
		return handleLib3MF4EOSException(pIBaseClass, Exception);
	}
	catch (std::exception & StdException) {
		return handleStdException(pIBaseClass, StdException);
	}
	catch (...) {
		return handleUnhandledException(pIBaseClass);
	}
}


